#!/usr/bin/env bash
set -euo pipefail
umask 077
VERSION="0.2.0-dev1"
EXPECTED_SHA256="30e39ed148c774ba010f72e5396b46e3dfbe7ab69ced4f94eac9a04dc84eb48c"
usage() {
  cat <<'HADS_NEXT_USAGE'
HADS Next 0.2.0-dev1 — samostatná vývojová aplikace, nikoli produkční RC.
Použití:
  bash HADS_Next_install_0.2.0-dev1.sh --verify
  bash HADS_Next_install_0.2.0-dev1.sh --extract-only /absolutni/novy-adresar
  bash HADS_Next_install_0.2.0-dev1.sh --install-dev
Instalační režim přidá pouze local_hads_next_investigation. Existující HADS nepřepisuje.
Původní Hermes je součástí balíčku. AI je vypnutá do výslovného souhlasu; živé opravy jsou vypnuté. Živá HAOS přejímka čeká.
HADS_NEXT_USAGE
}
MODE="${1:-}"
case "$MODE" in
  --help) [ "$#" = 1 ] || exit 2; usage; exit 0 ;;
  --verify|--install-dev) [ "$#" = 1 ] || { usage; exit 2; } ;;
  --extract-only) [ "$#" = 2 ] || { usage; exit 2; } ;;
  *) usage; exit 2 ;;
esac
command -v python3 >/dev/null || { echo 'Chybí python3 v terminálové aplikaci. Podrobnosti jsou v návodu DOCS.md.' >&2; exit 1; }
command -v base64 >/dev/null || { echo 'Chybí base64.' >&2; exit 1; }
STAGING="$(mktemp -d /tmp/hads-next-install.XXXXXX)"
cleanup() {
  case "$STAGING" in /tmp/hads-next-install.*) rm -rf -- "$STAGING" ;; esac
}
trap cleanup EXIT
